examples.template:
MonarchReactionBar(
    reactions,
    quickReactions: [{{quick.0}}, {{quick.1}}, {{quick.2}}, {{quick.3}}, {{quick.4}}, {{quick.5}}]
) { emoji, isReacted in
    // The product saves the reaction and updates `reactions`.
    print(emoji, isReacted)
}

examples.setupTemplate:
@State private var reactions = [
    MonarchReactionBarItem({{reactions.0.emoji}}, count: {{reactions.0.count}}, isReacted: {{reactions.0.reacted}}, label: {{reactions.0.label}}, reactedBy: {{reactions.0.title}}),
    MonarchReactionBarItem({{reactions.1.emoji}}, count: {{reactions.1.count}}, isReacted: {{reactions.1.reacted}}, label: {{reactions.1.label}}, reactedBy: {{reactions.1.title}}),
